#include <Arduino.h>

const uint8_t TRIG = 8;
const uint8_t ECHO = 9;
const uint8_t BUZZER = 6;
const uint8_t LED = 13;
const int DARK_THRESHOLD = 500;
bool alarming = false;
bool firstSample = true;
bool soundOn = false;
unsigned long lastSample = 0;
unsigned long alarmStart = 0;

float readDistanceCm() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  unsigned long duration = pulseIn(ECHO, HIGH, 30000UL);
  if (duration == 0) return -1.0f;
  return duration * 0.0343f / 2.0f;
}

void setup() {
  pinMode(A0, INPUT);
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  pinMode(BUZZER, OUTPUT);
  pinMode(LED, OUTPUT);
  digitalWrite(TRIG, LOW);
  digitalWrite(LED, LOW);
  noTone(BUZZER);
  Serial.begin(9600);
}

void loop() {
  unsigned long now = millis();
  if (firstSample || now - lastSample >= 70UL) {
    firstSample = false;
    lastSample = now;
    int light = analogRead(A0);
    float distance = readDistanceCm();
    bool nextAlarm = light < DARK_THRESHOLD && distance > 0.0f && distance <= 20.0f;
    if (nextAlarm && !alarming) {
      alarmStart = millis();
      Serial.println("alarm");
    }
    alarming = nextAlarm;
  }
  now = millis();
  bool activePhase = alarming && ((now - alarmStart) % 500UL < 250UL);
  digitalWrite(LED, activePhase ? HIGH : LOW);
  if (activePhase != soundOn) {
    soundOn = activePhase;
    if (soundOn) tone(BUZZER, 2000);
    else noTone(BUZZER);
  }
}
